"""Level Factory 0.228.0: `approve candidate_selected` refuses a candidate the mission's plan never builds (the
factory's roadmap 278).

The factory's cold run 9362 named seed 9281 against a batch whose seed_base was 9054; approve warned, recorded it, and
the functional lock refused it a step later as protecting nothing. A mission's candidates are its batch's before any
job runs, so a candidate outside them is refused now, the planned ones named, nothing recorded.

What it changes (anchored; each file pinned by hash; nothing written on a miss):
  * apps/cli/commands/__init__.py -- `_refuse_bad_candidate` asks `_plan_for` for the mission's candidates.
  * tests/unit/test_candidate_guard.py (new).
  * VERSION 0.227.0 -> 0.228.0, CHANGELOG.

Generated by `patches/lf_candidate_guard/gen_lf_candidate_guard.py` from a proven clone; its records are beside it.

    python patches/patch_lf_candidate_guard.py
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
LF = ROOT / "level_factory"
PINS = {'apps/cli/commands/__init__.py': '9b99704ca7622d5c'}
EDITS = {'apps/cli/commands/__init__.py': [('lines 3383-3384', '    cannot possibly name a job is wrong at any point in the order.\n    """\n', '    cannot possibly name a job is wrong at any point in the order.\n\n    MEMBERSHIP OF THE PLAN is refused too (0.228.0, the factory\'s roadmap\n    278), and it is not the ordering question: a mission\'s candidates are\n    its batch\'s -- `planner.derive_seeds(seed_base, candidate_count)` --\n    before any job has run, so a candidate outside them is one no job will\n    ever build. The factory\'s cold run 9362 named seed 9281 against a\n    batch whose seed_base was 9054: this warned "will resolve once that\n    job runs", recorded it, and the functional lock refused it a step\n    later as protecting nothing. A mission no batch holds keeps the\n    warning: there is no plan to ask.\n    """\n'), ('lines 3390-3391', '              f"{mission_id}.candidate.seed_<number>", file=sys.stderr)\n        print("  nothing is recorded; the gate is not approved",\n', '              f"{mission_id}.candidate.seed_<number>", file=sys.stderr)\n        print("  nothing is recorded; the gate is not approved",\n              file=sys.stderr)\n        return EXIT_BLOCKED\n    try:\n        _bid, _batch, _model, plan = _plan_for(ws, mission_id, None)\n        planned = list(plan.candidate_ids)\n    except SystemExit:\n        planned = []\n    if planned and str(candidate).strip() not in planned:\n        seeds = ", ".join(c.rsplit(".", 1)[-1] for c in planned)\n        print(f"refusing --candidate {candidate!r}: not one of "\n              f"{mission_id}\'s candidates ({seeds}) -- name one of them, "\n              f"or set its batch\'s seed_base to that seed and plan again",\n              file=sys.stderr)\n        print("  nothing is recorded; the gate is not approved",\n')]}
NEW_FILES = {'tests/unit/test_candidate_guard.py': '"""`approve candidate_selected` refuses a candidate the mission\'s plan never builds (0.228.0, the factory\'s roadmap 278).\n\nThe factory\'s cold run 9362 named seed 9281 against a batch whose seed_base was 9054. The approve WARNED -- "no\nbank_block_001.lot_assemble.candidate.seed_9281 yet; the selection is recorded and will resolve once that job runs" --\nand recorded it, and the functional lock refused it a step later as protecting nothing. A mission\'s candidates are its\nbatch\'s (`planner.derive_seeds`) before any job runs, so membership is not the ordering question the warning leaves\nopen. These build a workspace\'s batch and brief in a temporary folder; nothing runs a tool.\n"""\nimport json\nimport sys\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport pytest\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\n\nfrom apps.cli import commands\nfrom packages.project_store.workspace import Workspace\n\nM = "bank_block_001"\n\n\n@pytest.fixture()\ndef ws(tmp_path):\n    root = tmp_path / "ws"\n    batch = root / "batches" / "cold_9362"\n    (batch / "missions" / M / "brief").mkdir(parents=True)\n    (batch / "batch.json").write_text(json.dumps({"batch_id": "cold_9362", "seed_base": 9054,\n                                                  "missions": [M]}), encoding="utf-8")\n    (batch / "missions" / M / "brief" / "brief.json").write_text(\n        json.dumps({"mission_id": M, "display_name": "Bank block", "candidate_count": 3}), encoding="utf-8")\n    (root / "factory.project.json").write_text(json.dumps({"name": "test"}), encoding="utf-8")\n    return Workspace(root=root)\n\n\ndef test_a_seed_the_plan_never_builds_is_refused_and_the_planned_ones_named(ws, capsys):\n    """FAILS ON 0.227.0, which warned and recorded the selection."""\n    assert commands._refuse_bad_candidate(ws, M, M + ".candidate.seed_9281") == commands.EXIT_BLOCKED\n    err = capsys.readouterr().err\n    assert "not one of bank_block_001\'s candidates (seed_9054, seed_9155, seed_9256)" in err, err\n    assert "nothing is recorded" in err\n\n\ndef test_a_planned_seed_passes_and_is_warned_about_until_its_job_runs(ws, capsys):\n    """The ordering question stays open: a planned candidate selected before the shell leg is recorded, with the\n    warning, and once its lot_assemble job exists the warning goes."""\n    assert commands._refuse_bad_candidate(ws, M, M + ".candidate.seed_9155") == commands.EXIT_OK\n    assert "WARNING no bank_block_001.lot_assemble.candidate.seed_9155 yet" in capsys.readouterr().err\n    (ws.jobs_dir / (M + ".lot_assemble.candidate.seed_9155")).mkdir(parents=True)\n    assert commands._refuse_bad_candidate(ws, M, M + ".candidate.seed_9155") == commands.EXIT_OK\n    assert "WARNING" not in capsys.readouterr().err\n\n\ndef test_a_malformed_id_is_still_refused(ws, capsys):\n    assert commands._refuse_bad_candidate(ws, M, M + ".candidate.seed_XXXX") == commands.EXIT_BLOCKED\n    assert "expected bank_block_001.candidate.seed_<number>" in capsys.readouterr().err\n\n\ndef test_a_mission_no_batch_holds_keeps_the_warning(tmp_path, capsys):\n    """No plan to ask, so the old path: the shape passes and the warning prints."""\n    empty = Workspace(root=tmp_path / "empty")\n    assert commands._refuse_bad_candidate(empty, "nowhere_001", "nowhere_001.candidate.seed_1") == commands.EXIT_OK\n    assert "WARNING" in capsys.readouterr().err\n\n\ndef test_approve_records_nothing_for_a_refused_seed(ws):\n    """Through `cmd_approve`: refused before `store.record`, so no approved gate and no selection marker."""\n    args = SimpleNamespace(chdir=str(ws.root), mission_id=M, gate="candidate_selected",\n                           candidate=M + ".candidate.seed_9281", by="test", note="")\n    assert commands.cmd_approve(args) == commands.EXIT_BLOCKED\n    approvals = ws.internal_dir / "approvals"\n    assert not (approvals / (M + ".selected")).exists()\n    assert not any(approvals.glob("*")) if approvals.exists() else True\n'}
CHANGELOG = '## [0.228.0] - `approve candidate_selected` refuses a candidate the mission\'s plan never builds\n\n**Found by the factory\'s cold run 9362** (its roadmap 278). The run named seed 9281 against a batch whose\n`seed_base` was 9054, so the shell leg built the candidates 9054, 9155 and 9256. `approve candidate_selected\n--candidate bank_block_001.candidate.seed_9281` warned -- "no bank_block_001.lot_assemble.candidate.seed_9281 yet;\nthe selection is recorded and will resolve once that job runs" -- and recorded it; no job ever would, and the next\napproval, `functional_shell_locked`, refused the lock as protecting nothing, a long way from the cause.\n\n`_refuse_bad_candidate` refused a malformed id and only warned about a missing job, on purpose: whether lot_assemble\nhas run when a candidate is selected is an ordering question it has no business deciding. Whether a candidate is one\nof the mission\'s is not that question. A mission\'s candidates are its batch\'s -- `planner.derive_seeds(seed_base,\ncandidate_count)` through `_plan_for` -- before any job runs, so it now refuses a candidate outside them, names the\nones there are, and records nothing. A planned candidate whose job has not run yet is recorded with the warning, as\nbefore; a mission no batch holds keeps the old path, the warning, having no plan to ask.\n\n### Tests\n- `tests/unit/test_candidate_guard.py` (new), on a workspace\'s batch and brief built in a temporary folder: a seed the\n  plan never builds is refused and the planned seeds named; a planned seed passes, warned about until its\n  lot_assemble job exists; a malformed id is still refused; a mission no batch holds keeps the warning; `cmd_approve`\n  records no gate and no selection for a refused seed. The first and the last fail on 0.227.0 and the other three pass\n  there, the behaviour this keeps.\n\n'
OLD_VERSION, NEW_VERSION = '0.227.0', '0.228.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
